def create_identifiers_for_existing_releases(apps, schema_editor):
    DatasetRelease = apps.get_model("datasets", "DatasetRelease")
    ResourceIdentifier = apps.get_model("datasets", "ResourceIdentifier")
    ResourceRelationship = apps.get_model("datasets", "ResourceRelationship")
    OutboxEvent = apps.get_model("datasets", "OutboxEvent")

    dataset_ids = (
        DatasetRelease.objects.filter(status__in=["published", "withdrawn"])
        .values_list("dataset_id", flat=True)
        .distinct()
    )
    for dataset_id in dataset_ids.iterator():
        releases = DatasetRelease.objects.filter(
            dataset_id=dataset_id,
            status__in=["published", "withdrawn"],
        ).order_by("major", "minor", "patch")
        has_publishable_release = releases.filter(status="published").exists()
        concept, _ = ResourceIdentifier.objects.get_or_create(
            dataset_id=dataset_id,
            scheme="doi",
            role="concept",
            defaults={
                "provider": "unconfigured",
                "registration_status": (
                    "pending" if has_publishable_release else "not_requested"
                ),
            },
        )
        for release in releases.iterator():
            is_published = release.status == "published"
            version, _ = ResourceIdentifier.objects.get_or_create(
                release_id=release.pk,
                scheme="doi",
                role="version",
                defaults={
                    "provider": "unconfigured",
                    "lifecycle_status": "active" if is_published else "withdrawn",
                    "registration_status": "pending" if is_published else "cancelled",
                },
            )
            ResourceRelationship.objects.get_or_create(
                subject_identifier_id=concept.pk,
                related_identifier_id=version.pk,
                relationship_type="hasVersion",
            )
            ResourceRelationship.objects.get_or_create(
                subject_identifier_id=version.pk,
                related_identifier_id=concept.pk,
                relationship_type="isVersionOf",
            )
            if is_published:
                OutboxEvent.objects.get_or_create(
                    idempotency_key=f"pid-register:{version.pk}",
                    defaults={
                        "event_type": "pid.register_identifier",
                        "payload": {"identifier_id": str(version.pk)},
                    },
                )
        if has_publishable_release:
            OutboxEvent.objects.get_or_create(
                idempotency_key=f"pid-register:{concept.pk}",
                defaults={
                    "event_type": "pid.register_identifier",
                    "payload": {"identifier_id": str(concept.pk)},
                },
            )


